#include <iostream>
using namespace std;

class Employee{

    string Name;
    string Company;
    int Age;
    
    public:
// Constructor is a special type of method that is invoked everytime an object is created, it is one of the new features of C++ which are not present in C

// Default constructor: automatically generated by compiler

// However, we create our own constructors to initialize the variables or some other functions

    /*
    * RULE 1: Same name as class
    * RULE 2: Must be public
    * RULE 3: No return type
    * RULE 4: Once we create our own constructors we can't use the default constructor
    */

    /*
    * Just like a function, a constructor can have parameters and thus they can be overloaded(doing multiple things with multiple functions that share the same name and same class)
    */

    Employee(){ // non-parameterised constructor
        Name = "Default Name";
        Company = "Default Company";
        Age = 0;
    }
    
    Employee(string name, string company){ // parameterised constructor
        Name = name; // if there are 2 variables, then the left one is ALWAYS the variable whose value is being assigned while right one IS THE VALUE
        Company = company;
        Age = 25;
    }

    Employee(string Name, string Company, int Age){
        this->Name = Name; //! 'this' is used to refer to the current object, we use this if local variable name == argument name of function
        this->Company = Company; //* this-> helps the compiler know that we are referring to local variable
        this->Age = Age;
    }

    void Introduce(){
        cout << "Name:" << Name << endl;
        cout << "Company:" << Company << endl;
        cout << "Age:" << Age << endl;
    }

};

int main() {
    Employee emp1 = Employee("Yuvraj", "Amazon", 19); // Constructor is invoked here but we can choose which one to use
    
    emp1.Introduce();
    
    Employee emp2 = Employee("Raj", "Google"); // constructor with 2 arguments
    
    emp2.Introduce();

    Employee emp3 = Employee(); // no arguments constructor
    
    emp3.Introduce();
    
    return 0;
}